  const lastNodeSchemaSync = (
    await getLastNodeSchemaSyncTime(supabaseClient, context.spaceId)
  ).getTime();
  const lastRelationSchemaSync = (
    await getLastRelationSchemaSyncTime(supabaseClient, context.spaceId)
